/* the offline cache of the web version. Generated by tools/make-sw.py: do not edit by hand.
   Every file is cached on the first visit. A new version installs in the background and waits: the app shows a bar
   "גרסה חדשה זמינה" and, on a tap, asks it to take over (skipWaiting); it then deletes the caches of older versions */
const CACHE = 'aramit-shabbat-1.6.11';
const FILES = [ "./", "app.js", "bank.js", "concepts.js", "content.js", "daily-boards.js", "data.js", "fonts/assistant-hebrew-400-normal.woff2", "fonts/assistant-hebrew-600-normal.woff2", "fonts/assistant-hebrew-700-normal.woff2", "fonts/assistant-latin-400-normal.woff2", "fonts/assistant-latin-600-normal.woff2", "fonts/assistant-latin-700-normal.woff2", "fonts/frank-ruhl-libre-hebrew-500-normal.woff2", "fonts/frank-ruhl-libre-hebrew-700-normal.woff2", "fonts/frank-ruhl-libre-hebrew-900-normal.woff2", "fonts/frank-ruhl-libre-latin-700-normal.woff2", "hewords.js", "icons/apple-touch-icon.png", "icons/favicon-48.png", "icons/icon-192.png", "icons/icon-512.png", "icons/maskable-192.png", "icons/maskable-512.png", "index.html", "manifest.json", "occ.js", "style.css", "wdclues.js", "xwclues.js" ];
self.addEventListener('install', ev => {
  ev.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES)));
});
self.addEventListener('message', ev => { if (ev.data && ev.data.type === 'skip-waiting') self.skipWaiting(); });
self.addEventListener('activate', ev => {
  ev.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith('aramit-shabbat-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});
self.addEventListener('fetch', ev => {
  const req = ev.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  ev.respondWith(caches.open(CACHE).then(c => c.match(req, { ignoreSearch: true }).then(hit => {
    if (hit) return hit;
    return fetch(req).then(res => { if (res.ok && res.type === 'basic') c.put(req, res.clone()); return res; })
      .catch(() => req.mode === 'navigate' ? c.match('index.html') : Response.error());
  })));
});
/* the daily reminder of the web version: when the browser wakes the worker (a site added to the home screen, Chrome on
   Android), the reminder shows once a day, after the hour chosen in the settings. A tap opens the short daily round */
self.addEventListener('periodicsync', ev => { if (ev.tag === 'aramit-reminder') ev.waitUntil(remind()); });
async function remind() {
  const c = await caches.open('aramit-reminder'), url = self.registration.scope + 'reminder.json', res = await c.match(url);
  if (!res) return;
  const r = await res.json(), now = new Date(), day = now.getFullYear() + '-' + (now.getMonth() + 1) + '-' + now.getDate();
  if (!r.on || r.last === day || now.getHours() * 60 + now.getMinutes() < r.h * 60 + r.m) return;
  r.last = day; await c.put(url, new Response(JSON.stringify(r), { headers: { 'content-type': 'application/json' } }));
  await self.registration.showNotification('חזרה יומית', { body: '10 מילים ומושגים ממסכת שבת', icon: 'icons/icon-192.png', lang: 'he', dir: 'rtl', tag: 'aramit-daily', data: { daily: 1 } });
}
self.addEventListener('notificationclick', ev => {
  ev.notification.close();
  ev.waitUntil(self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(list => {
    for (const w of list) { w.postMessage({ daily: 1 }); return w.focus(); }
    return self.clients.openWindow(self.registration.scope + '?daily=1');
  }));
});
